'use client';

import { useSearchParams } from 'next/navigation';
import { useState, useEffect } from 'react';

export default function MenuSearchResultContent() {
  const [menuList, setMenuList] = useState([]);
  // 쿼리 스트링 객체 가져오기
  const searchParam = useSearchParams();
  // URL 뒤에 붙어 있는 쿼리 스트링 값을 읽을 때 사용

  // '?menuName=열무' 에서 '열무' 라는 값 추출
  const menuName = searchParam.get('menuName');
  console.log(menuName); //열무라고 검색하면 '열무'

  useEffect(() => {
    setMenuList(searchMenu(menuName));
  }, [menuName]);

  return (
    <>
      <h1>검색 결과!</h1>
      <div>
        {menuList.map((menu) => (
          <MenuItem key={menu.menucode} menu={menu} />
        ))}
      </div>
    </>
  );
}
